import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"Research Runtime Center V5.0","description":"","frontmatter":{"title":"Research Runtime Center V5.0","outline":"deep"},"headers":[],"relativePath":"en/runtime/v5.md","filePath":"en/runtime/v5.md","lastUpdated":1786503324000}'),r={name:"en/runtime/v5.md"};function s(o,e,d,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="research-runtime-center-v5-0" tabindex="-1">Research Runtime Center V5.0 <a class="header-anchor" href="#research-runtime-center-v5-0" aria-label="Permalink to &quot;Research Runtime Center V5.0&quot;">​</a></h1><p><strong>Status:</strong> Frozen architecture<br><strong>Scheduler:</strong> Research Runtime Scheduler V3.0<br><strong>Effective:</strong> 2026-08-05<br><strong>Timezone:</strong> Asia/Shanghai</p><h2 id="why-v5-exists" tabindex="-1">Why V5 exists <a class="header-anchor" href="#why-v5-exists" aria-label="Permalink to &quot;Why V5 exists&quot;">​</a></h2><p>V4 mixed long-term Research Program work with the Daily production line. The 09:00 Engine advanced a long-term object before the 10:00 same-day topic decision, so newly discovered topics could not complete Reading and Analysis before the 15:00 Production gate.</p><p>V5 removes that structural conflict.</p><h2 id="four-independent-runtime-systems" tabindex="-1">Four independent runtime systems <a class="header-anchor" href="#four-independent-runtime-systems" aria-label="Permalink to &quot;Four independent runtime systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime</th><th>Responsibility</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Daily</td><td>Same-day discovery, research, production and publication</td><td>Same-day signals</td><td>Released Daily Research</td></tr><tr><td>Weekly</td><td>Independent AI Research Brief</td><td>Previous seven days of validated Daily Research</td><td>Material changes, connections, evidence and disputes, judgments, and open questions</td></tr><tr><td>Academic</td><td>Formal academic observation</td><td>Paper, Benchmark, Specification or Institution</td><td>Academic Observation</td></tr><tr><td>Program</td><td>Long-term governed research</td><td>Independent Program queues</td><td>Program transition and Program publication</td></tr></tbody></table><p>The four systems have separate records, queues and operational timelines.</p><h2 id="daily-runtime" tabindex="-1">Daily Runtime <a class="header-anchor" href="#daily-runtime" aria-label="Permalink to &quot;Daily Runtime&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Discovery → Signal Pool</span></span>
<span class="line"><span>10:00 Queue → Today&#39;s Research Plan</span></span>
<span class="line"><span>11:00 Reading → Reading Result</span></span>
<span class="line"><span>13:00 Analysis → Research Object</span></span>
<span class="line"><span>15:00 Production → Publication Candidate</span></span>
<span class="line"><span>20:00 Publication → GitHub + Website + Commit Verify + Release</span></span></code></pre></div><p>The three Daily columns are Digital Employee, Industry Architecture and Open-source Engineering. Each column must be <code>Selected</code> or <code>No Selection</code> every day.</p><h2 id="stage-authority" tabindex="-1">Stage authority <a class="header-anchor" href="#stage-authority" aria-label="Permalink to &quot;Stage authority&quot;">​</a></h2><ul><li>Discovery executes the three Research Intelligence profiles.</li><li>Queue performs three-column triage only.</li><li>Reading executes Skill 03.</li><li>Analysis executes Skill 04.</li><li>Production executes Skills 05–08.</li><li>Publication performs release only.</li></ul><p>From 2026-08-12, Analysis and Production also apply Editorial Architecture V2: research-question-first analysis, extensible article-type identification, dynamic content modules, evidence identities, research independence, six editorial gates, and an optional separately framed Community Edition. The V5 Runtime topology and stage order remain unchanged.</p><p>Production has one legal input: <code>Research Object</code>. Publication has one legal input: a complete <code>Publication Candidate</code>.</p><h2 id="independent-schedules" tabindex="-1">Independent schedules <a class="header-anchor" href="#independent-schedules" aria-label="Permalink to &quot;Independent schedules&quot;">​</a></h2><ul><li>Weekly Runtime: Sunday 20:30.</li><li>Academic Runtime: Wednesday 16:00.</li><li>Research Program Runtime: Monday 12:00.</li></ul><p>Program covers TMPA, FCoP, CodeFlowMu, Digital Employee and Research Operating System. It never enters Daily Runtime.</p><h2 id="runtime-records" tabindex="-1">Runtime Records <a class="header-anchor" href="#runtime-records" aria-label="Permalink to &quot;Runtime Records&quot;">​</a></h2><p>V5 creates separate JSON records under:</p><ul><li><code>research/runtime/records/daily/</code></li><li><code>research/runtime/records/weekly/</code></li><li><code>research/runtime/records/academic/</code></li><li><code>research/runtime/records/program/</code></li></ul><p>Every terminal shift reports Input, Work Result, Output, Next, Metrics, Evidence and Artifacts.</p><h2 id="github-actions-and-chatgpt-workers" tabindex="-1">GitHub Actions and ChatGPT workers <a class="header-anchor" href="#github-actions-and-chatgpt-workers" aria-label="Permalink to &quot;GitHub Actions and ChatGPT workers&quot;">​</a></h2><p>GitHub Actions opens execution slots. ChatGPT workers perform the actual research. An opened slot remains <code>Waiting</code> until the worker writes a valid result. Scheduler execution must never manufacture <code>Completed</code>.</p><h2 id="freeze-rule" tabindex="-1">Freeze rule <a class="header-anchor" href="#freeze-rule" aria-label="Permalink to &quot;Freeze rule&quot;">​</a></h2><p>After V5.0, the four-system separation, the six Daily stages and the nine Scheduler V3 task identities are frozen. Future work is optimization: source quality, worker effectiveness, metrics, UX, evidence quality and publication quality.</p>`,26)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
